// Used only on the internal /partners sales-preview page to show a prospective
// partner what their featured card will look like. Never rendered on public
// area/category pages.
export const exampleProfessional: Professional = {
  id: "example-preview",
  name: "Your Clinic Name",
  categorySlug: "dentist",
  areaSlug: "poblenou",
  partnerTier: "top",
  partnerSince: "2026-01-01",
  isPlaceholder: true,
  specialties: ["Implants", "Invisalign", "Cosmetic dentistry"],
  languages: ["English", "Spanish", "Catalan"],
  addressArea: "Poblenou, Barcelona",
  lat: 41.4037049,
  lng: 2.2033841,
  phoneDisplay: "+34 9XX XXX XXX",
  bookingUrl: "#",
  ratingLabel: "Recommended partner",
};

// "top" (max 1 per area+category, enforced by hand when assigning partnerTier
// in the data, not here) always leads, then "recommended" partners ordered
// oldest-first by partnerSince (first-come-first-served, not pay-to-jump-the-
// queue), then everyone else in source order.
const TIER_RANK: Record<string, number> = { top: 0, recommended: 1 };

export function getProfessionals(areaSlug: string, categorySlug: string): Professional[] {
  return professionals
    .filter((p) => p.areaSlug === areaSlug && p.categorySlug === categorySlug)
    .sort((a, b) => {
      const rankA = a.partnerTier ? TIER_RANK[a.partnerTier] : 2;
      const rankB = b.partnerTier ? TIER_RANK[b.partnerTier] : 2;
      if (rankA !== rankB) return rankA - rankB;
      if (rankA === 1) {
        // both "recommended": oldest partnerSince first
        const sinceA = a.partnerSince ? Date.parse(a.partnerSince) : Infinity;
        const sinceB = b.partnerSince ? Date.parse(b.partnerSince) : Infinity;
        return sinceA - sinceB;
      }
      return 0;
    });
}
